import {money,number,parseMoney,summarize,inMonth,breakdown,dailyExpenses,csv,categoryBudgetSummary,setMonthlySalary,allocationSummary,categoryLabel} from './finance.js';
import {initialState,loadState,saveState,demoTransactions} from './storage.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<i data-lucide="${name}"></i>`, today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Bucharest'}).format(new Date());
let state,storageFailed=false;
try{state=loadState();}catch{state=initialState();storageFailed=true;}
let month=today().slice(0,7), page='dashboard', filter={search:'',category:'',type:''},tablePage=1,modal=null,toastTimer;
const pages={dashboard:['Dashboard','Banii tăi, în perspectivă','O privire de ansamblu. Decizii mai bune, în fiecare zi.'],transactions:['Tranzacții','Fiecare leu are o poveste','Toate veniturile și cheltuielile tale, într-un singur loc.'],budgets:['Bugete','Un plan pentru banii tăi','Stabilește o limită lunară și urmărește-ți progresul.'],categories:['Categorii','Totul, la locul potrivit','Organizează-ți cheltuielile în felul tău.'],reports:['Rapoarte','Cifre care spun mai mult','Descoperă unde se duc banii și cum poți economisi.'],settings:['Setări','Exact așa cum îți place','Un spațiu personal, configurat de tine.']};
function icons(){window.lucide?.createIcons({attrs:{'aria-hidden':'true','stroke-width':1.7}});}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function persist(next){if(storageFailed)throw Error('Datele existente nu pot fi citite. Nu le suprascriem. Verifică stocarea browserului.');try{saveState(next);}catch{throw Error('Salvarea a eșuat. Verifică spațiul disponibil și permisiunile browserului.');}state=next;}
function mutate(fn){const next=structuredClone(state);fn(next);persist(next);}
function applyAppearance(){document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('collapsed',!!state.collapsed);$('#theme').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#theme').setAttribute('aria-label',state.theme==='dark'?'Activează tema luminoasă':'Activează tema întunecată');$('#collapse').setAttribute('aria-expanded',String(!state.collapsed));}
const monthRows=()=>inMonth(state.transactions,month), budget=()=>state.budgets[month]||0;
function monthName(){return new Date(month+'-01T12:00:00').toLocaleDateString('ro-RO',{month:'long',year:'numeric'});}
function metric(title,value,ico,kind,sub,featured=false){return `<article class="metric ${featured?'featured':''}"><div class="metric-top"><span>${title}</span><span class="metric-icon ${kind}">${icon(ico)}</span></div><div class="metric-value">${number(value)}<span class="currency">RON</span></div><div class="metric-bottom">${sub}</div></article>`;}
function metrics(){const s=summarize(monthRows(),budget());return `<div class="section-caption"><span>${icon('circle-dot')} REZUMATUL LUNII</span><span>Sume în RON · ${monthRows().length} tranzacții</span></div><section class="metrics" aria-label="Rezumat financiar">${metric('Sold disponibil',s.balance,'wallet','','Venituri minus cheltuieli',true)}${metric('Venituri totale',s.income,'arrow-down-left','green',`<span class="green">${icon('arrow-down-left')}</span> ${monthRows().filter(t=>t.type==='income').length} încasări în această lună`)}${metric('Cheltuieli totale',s.expenses,'arrow-up-right','red',`<span class="red">${icon('arrow-up-right')}</span> ${monthRows().filter(t=>t.type==='expense').length} plăți în această lună`)}<article class="metric"><div class="metric-top"><span>Buget rămas</span><span class="metric-icon">${icon('chart-pie')}</span></div><div class="metric-value ${budget()&&s.remaining<0?'red':''}">${budget()?number(s.remaining):'—'}<span class="currency">RON</span></div><div class="budget-progress"><div class="progress"><span style="width:${Math.min(s.used,100)}%;${s.used>100?'background:var(--red)':''}"></span></div><div><span>${budget()?Math.round(s.used)+'% utilizat':'Niciun buget stabilit'}</span><span>${budget()?'din '+number(budget())+' RON':''}</span></div></div><button class="tiny-edit" data-action="budget" aria-label="Editează bugetul lunar">${icon('pencil')}</button></article></section>`;}
function lineChart(){const rows=monthRows(),data=dailyExpenses(rows,month),s=summarize(rows),max=Math.max(10000,...data.map(d=>d.total)),ceil=Math.ceil(max/10000)*10000;const x=i=>40+i/(data.length-1)*500,y=v=>168-v/ceil*138,points=data.map((d,i)=>`${x(i)},${y(d.total)}`).join(' ');return `<article class="panel"><div class="panel-head"><div><h2>Evoluția cheltuielilor</h2><p>Un ritm mai clar, zi de zi.</p></div><span class="chart-legend"><i class="dot" style="background:#818cf8"></i>Cheltuieli</span></div><div class="chart-wrap"><svg class="line-chart" viewBox="0 0 560 200" role="img" aria-label="Cheltuieli zilnice în ${esc(monthName())}: ${esc(money(s.expenses))}"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#818cf8" stop-opacity=".24"/><stop offset="100%" stop-color="#818cf8" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{let v=ceil*i/3;return `<line class="grid" x1="40" x2="540" y1="${y(v)}" y2="${y(v)}"/><text x="30" y="${y(v)+3}" text-anchor="end">${number(v)}</text>`;}).join('')}<polygon points="40,168 ${points} 540,168" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#818cf8" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>${data.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d.total)}" r="5" fill="transparent"><title>${d.day} ${monthName()}: ${money(d.total)}</title></circle>`).join('')}${[1,5,10,15,20,25,data.length].map(d=>`<text x="${x(d-1)}" y="192" text-anchor="middle">${String(d).padStart(2,'0')}</text>`).join('')}</svg></div><div class="chart-summary"><span>Medie zilnică <strong>${money(Math.round(s.expenses/data.length))}</strong></span><span>Total <strong>${money(s.expenses)}</strong></span></div></article>`;}
function donutChart(){const data=breakdown(monthRows(),state.categories),total=data.reduce((s,c)=>s+c.total,0);let offset=0;return `<article class="panel"><div class="panel-head"><div><h2>Unde se duc banii</h2><p>Cheltuielile tale, pe categorii.</p></div><span class="chart-legend">RON</span></div><div class="donut-layout"><div class="donut"><svg viewBox="0 0 120 120" role="img" aria-label="Distribuția cheltuielilor pe categorii"><circle cx="60" cy="60" r="49" fill="none" stroke="var(--line)" stroke-width="11"/>${data.map(c=>{const part=c.total/total*307.876;const result=`<circle cx="60" cy="60" r="49" fill="none" stroke="${c.color}" stroke-width="11" stroke-dasharray="${Math.max(0,part-2)} ${307.876-Math.max(0,part-2)}" stroke-dashoffset="${-offset}"><title>${esc(c.name)}: ${money(c.total)} (${(c.total/total*100).toFixed(1)}%)</title></circle>`;offset+=part;return result;}).join('')}</svg><div class="donut-center"><span>Total cheltuieli</span><strong>${number(total)}</strong><small>RON</small></div></div><div class="category-legend">${data.length?data.map(c=>`<div class="legend-row"><i class="dot" style="background:${c.color}"></i><div>${esc(c.name)}<small>${money(c.total)}</small></div><strong>${Math.round(c.total/total*100)}%</strong></div>`).join(''):`<div class="empty-chart">Fiecare leu contează.<br>Adaugă o cheltuială pentru a vedea distribuția.</div>`}</div></div></article>`;}
function charts(){return `<section class="charts" aria-label="Grafice financiare">${lineChart()}${donutChart()}</section>`;}
function filtered(){const q=filter.search.toLocaleLowerCase('ro-RO');return monthRows().filter(t=>(!filter.category||t.category===filter.category||state.categories.find(c=>c.id===t.category)?.parentId===filter.category)&&(!filter.type||t.type===filter.type)&&(!q||(t.name+' '+(t.description||'')).toLocaleLowerCase('ro-RO').includes(q))).sort((a,b)=>b.date.localeCompare(a.date));}
function transactionRows(){const rows=filtered(),limit=page==='dashboard'?5:10,totalPages=Math.max(1,Math.ceil(rows.length/limit));tablePage=Math.min(tablePage,totalPages);const visible=rows.slice((tablePage-1)*limit,tablePage*limit);return `<div class="table-scroll"><table><thead><tr><th>Denumire</th><th>Categorie</th><th>Dată</th><th>Tip</th><th style="text-align:right">Sumă</th><th aria-label="Acțiuni"></th></tr></thead><tbody>${visible.map(t=>{const c=state.categories.find(c=>c.id===t.category);return `<tr><td><div class="transaction-name"><span class="tile" style="color:${c?.color||'#818cf8'}">${icon(t.type==='income'?'arrow-down-left':c?.icon||'receipt-text')}</span>${esc(t.name)}</div></td><td><span class="tag" style="--tag:${c?.color||'#94a3b8'}">${esc(categoryLabel(c,state.categories))}</span></td><td>${new Date(t.date+'T12:00:00').toLocaleDateString('ro-RO',{day:'2-digit',month:'short',year:'numeric'})}</td><td><span class="type-tag ${t.type==='income'?'green':'muted'}"><i></i>${t.type==='income'?'Venit':'Cheltuială'}</span></td><td class="amount ${t.type==='income'?'income':''}">${t.type==='income'?'+':'−'}${money(t.amount)}</td><td class="row-actions"><button class="icon-button" data-edit="${t.id}" aria-label="Editează ${esc(t.name)}">${icon('pencil')}</button><button class="icon-button" data-delete="${t.id}" aria-label="Șterge ${esc(t.name)}">${icon('trash-2')}</button></td></tr>`;}).join('')}</tbody></table></div>${!visible.length?`<div class="empty-state"><span class="empty-icon">${icon('arrow-left-right')}</span><h3>${monthRows().length?'Nicio tranzacție găsită':'Un nou început pentru banii tăi'}</h3><p>${monthRows().length?'Încearcă altă căutare sau modifică filtrele.':'Adaugă prima tranzacție. Noi ne ocupăm de calcule.'}</p>${monthRows().length?'<button class="button" data-action="reset-filters">Resetează filtrele</button>':`<button class="button primary" data-action="add">${icon('plus')}Adaugă tranzacție</button>${!state.transactions.length?'<button class="button" data-action="demo">Explorează cu date demo</button>':''}`}</div>`:''}<div class="table-footer"><span>${rows.length?`${(tablePage-1)*limit+1}–${Math.min(tablePage*limit,rows.length)} din ${rows.length}`:'0'} tranzacții</span><div class="pagination"><span>Pagina ${tablePage} din ${totalPages}</span><button class="icon-button" data-action="table-prev" aria-label="Pagina anterioară" ${tablePage===1?'disabled':''}>${icon('chevron-left')}</button><button class="icon-button" data-action="table-next" aria-label="Pagina următoare" ${tablePage===totalPages?'disabled':''}>${icon('chevron-right')}</button></div></div>`;}
function transactions(){return `<section class="panel transactions-panel"><div class="panel-head"><div><h2>${page==='dashboard'?'Tranzacții recente':'Toate tranzacțiile'}</h2><p>Micile detalii care fac imaginea de ansamblu.</p></div>${page==='dashboard'?`<a href="#transactions" class="text-button">Vezi toate ${icon('arrow-up-right')}</a>`:''}</div><div class="filters"><div class="search">${icon('search')}<input id="search" type="search" placeholder="Caută o tranzacție..." aria-label="Caută tranzacții" value="${esc(filter.search)}"></div><select id="category-filter" aria-label="Filtrează după categorie"><option value="">Toate categoriile</option>${state.categories.map(c=>`<option value="${c.id}" ${filter.category===c.id?'selected':''}>${esc(categoryLabel(c,state.categories))}</option>`).join('')}</select><select id="type-filter" aria-label="Filtrează după tip"><option value="">Toate tipurile</option><option value="income" ${filter.type==='income'?'selected':''}>Venituri</option><option value="expense" ${filter.type==='expense'?'selected':''}>Cheltuieli</option></select><button class="button" data-action="export">${icon('download')}<span>Export CSV</span></button></div><div id="table-area">${transactionRows()}</div></section>`;}
function budgetView(){const s=summarize(monthRows(),budget());return `<div class="section-toolbar"><span>Buget lunar · ${esc(monthName())}</span><button class="button primary" data-action="budget">${icon('pencil')}Editează bugetul</button></div><section class="panel budget-card"><div class="section-body"><span class="eyebrow">BUGET ALOCAT</span><div class="large-value">${money(budget())}</div><div class="progress"><span style="width:${Math.min(s.used,100)}%;${s.used>100?'background:var(--red)':''}"></span></div><div class="budget-details"><span>${money(s.expenses)} cheltuiți</span><span>${budget()?Math.round(s.used)+'% utilizat':'Neconfigurat'}</span></div><h3>${!budget()?'O lună bună începe cu un plan.':s.remaining<0?'Ai depășit bugetul lunar.':'Mai ai '+money(s.remaining)+' la dispoziție.'}</h3><p>Bugetul este limita ta de cheltuieli pentru luna selectată. Îl poți modifica oricând, iar tranzacțiile tale vor rămâne salvate.</p><button class="button" data-action="budget">${icon('wallet')}${budget()?'Modifică bugetul':'Configurează bugetul'}</button> <a class="button" href="#categories">${icon('shapes')}Bugete pe categorii</a></div></section>`;}
function categoriesView(){
const categories=categoryBudgetSummary(state.transactions,state.categories,state.categoryBudgets,month),plan=allocationSummary(state.categories,state.categoryBudgets,month,budget());
const card=c=>`<article class="panel category-budget-card" style="--tag:${c.color}"><div class="category-card"><span class="tile">${icon(c.icon)}</span><div><h3>${esc(c.name)}</h3><p>${c.parentId?'Subcategorie · '+esc(state.categories.find(parent=>parent.id===c.parentId)?.name||''):c.custom?'Categorie personalizată':'Categorie implicită'}</p></div>${c.custom?`<div class="row-actions"><button class="icon-button" data-edit-category="${c.id}" aria-label="Redenumește ${esc(c.name)}">${icon('pencil')}</button><button class="icon-button" data-delete-category="${c.id}" aria-label="Șterge categoria ${esc(c.name)}">${icon('trash-2')}</button></div>`:''}</div><div class="category-budget-body"><div class="category-allocation"><span>${c.id==='cat-4'?'Planificat pentru plată':'Buget alocat'}</span><strong>${c.allocated?money(c.allocated):'Neconfigurat'}</strong></div><div class="progress"><span style="width:${Math.min(c.used,100)}%;background:${c.used>100?'var(--red)':c.color}"></span></div><div class="category-budget-details"><span>${c.id==='cat-4'?'Achitat':'Cheltuit'}<strong>${money(c.spent)}</strong></span><span>${c.remaining!==null&&c.remaining<0?'Depășire':c.id==='cat-4'?'Rămas de plată':'Rămas'}<strong class="${c.remaining!==null&&c.remaining<0?'red':''}">${c.remaining===null?'—':money(Math.abs(c.remaining))}</strong></span></div><button class="button" data-category-budget="${c.id}">${icon(c.allocated?'pencil':'plus')}${c.allocated?'Editează bugetul':'Setează bugetul'}</button></div></article>`;
return `<section class="allocation-overview panel" aria-label="Repartizarea bugetului lunar"><div class="allocation-heading"><div><span class="eyebrow">BUGETUL TĂU · ${esc(monthName().toLocaleUpperCase('ro-RO'))}</span><h2>Fiecare leu are un loc.</h2></div><button class="button" data-action="salary">${icon('wallet')}${budget()?'Editează bugetul total':'Adaugă buget'}</button></div><div class="allocation-values"><div><span>Buget total (salariu)</span><strong>${money(plan.total)}</strong></div><div><span>Alocat pe categorii</span><strong>${money(plan.allocated)}</strong></div><div class="allocation-remaining"><span>${plan.unallocated<0?'Alocat peste buget':'Rămas de repartizat'}</span><strong class="${plan.unallocated<0?'red':'purple'}">${money(Math.abs(plan.unallocated))}</strong></div></div><div class="progress"><span style="width:${plan.total?Math.min(plan.allocated*100/plan.total,100):0}%;${plan.unallocated<0?'background:var(--red)':''}"></span></div><p>${plan.unallocated<0?'Alocările depășesc bugetul total. Poți ajusta sumele din categorii.':'Suma rămasă scade când aloci bani unei categorii și crește când reduci sau elimini o alocare.'} Cheltuielile se urmăresc separat în fiecare categorie.</p></section><div class="section-toolbar"><span>${categories.filter(c=>!c.isGroup&&!c.parentId).length+categories.filter(c=>c.isGroup).length} categorii · ${esc(monthName())}</span><button class="button primary" data-action="add-category">${icon('plus')}Adaugă categorie</button></div><section class="category-grid">${categories.filter(c=>!c.parentId).sort((a,b)=>{const order=['cat-car','cat-6','cat-7','cat-2','cat-3','cat-misc','cat-4'];return (order.includes(a.id)?order.indexOf(a.id):99)-(order.includes(b.id)?order.indexOf(b.id):99);}).map(c=>c.isGroup?`<section class="category-group panel"><div class="category-group-heading"><div><h2>${icon(c.icon)} ${esc(c.name)}</h2><p>Totalul include alocările subcategoriilor și eventualele alocări anterioare.</p></div><div><span>Total alocat <strong>${money(c.allocated)}</strong></span><span>Cheltuit <strong>${money(c.spent)}</strong></span></div></div><div class="category-grid">${categories.filter(child=>child.parentId===c.id).map(card).join('')}${((state.categoryBudgets?.[month]?.[c.id]||0)||monthRows().some(t=>t.type==='expense'&&t.category===c.id))?card({...c,isGroup:false,name:'Alocare anterioară · '+c.name,allocated:state.categoryBudgets?.[month]?.[c.id]||0,...(()=>{const allocated=state.categoryBudgets?.[month]?.[c.id]||0,spent=monthRows().filter(t=>t.type==='expense'&&t.category===c.id).reduce((sum,t)=>sum+t.amount,0);return {spent,remaining:allocated?allocated-spent:null,used:allocated?spent*100/allocated:0};})()}):''}</div></section>`:card(c)).join('')}</section>`;
}

function reportsView(){const s=summarize(monthRows(),budget()),expenses=monthRows().filter(t=>t.type==='expense'),largest=expenses.reduce((a,b)=>a.amount>b.amount?a:b,{amount:0,name:'—'});return `${metrics()}${charts()}<section class="panel"><div class="section-body"><h3>Dincolo de cifre</h3><div class="report-stat"><span>Rată de economisire</span><strong>${s.income?((s.balance/s.income)*100).toLocaleString('ro-RO',{maximumFractionDigits:1})+'%':'—'}</strong></div><div class="report-stat"><span>Cea mai mare cheltuială</span><strong>${esc(largest.name)}${largest.amount?' · '+money(largest.amount):''}</strong></div><div class="report-stat"><span>Valoare medie / cheltuială</span><strong>${money(expenses.length?Math.round(s.expenses/expenses.length):0)}</strong></div><p>Rata de economisire = (venituri − cheltuieli) / venituri. În această versiune, sumele din categoria Economii sunt tratate ca ieșiri din buget.</p><button class="button" data-action="report-export">${icon('download')}Exportă luna în CSV</button></div></section>`;}
function settingsView(){return `<div class="settings-grid"><section class="panel section-body settings-row"><div><h3>Aspectul aplicației</h3><p>Alege tema în care te simți cel mai bine.</p></div><button class="button" data-action="theme">${icon(state.theme==='dark'?'sun':'moon')}${state.theme==='dark'?'Activează Light Mode':'Activează Dark Mode'}</button></section><section class="panel section-body settings-row"><div><h3>Datele tale rămân ale tale</h3><p>Tranzacțiile sunt salvate în acest browser, pe acest dispozitiv. Ștergerea datelor browserului le elimină. Exportă periodic o copie CSV.</p></div><button class="button" data-action="export-all">${icon('download')}Exportă toate datele</button></section><section class="panel section-body settings-row"><div><h3>Explorează JARVIS</h3><p>Adaugă un set demonstrativ în luna selectată. Disponibil numai când nu există tranzacții salvate.</p></div><button class="button" data-action="demo" ${state.transactions.length?'disabled':''}>${icon('sparkles')}Date demo</button></section><section class="panel section-body"><h3>JARVIS Expense Manager</h3><p>Versiunea 1.0 · Monedă: RON · Format: România<br>Fără autentificare, sincronizare cloud sau integrare bancară.</p></section></div>`;}
function salaryPlanning(){
const linked=state.transactions.find(t=>t.salaryMonth===month),allocated=Object.values(state.categoryBudgets?.[month]||{}).reduce((sum,n)=>sum+n,0),unallocated=budget()-allocated;
return `<section class="panel salary-planning"><div><span class="eyebrow">PLANUL TĂU PENTRU ${esc(monthName().toLocaleUpperCase('ro-RO'))}</span><h2>${linked?'Salariul tău, împărțit cu sens.':'Începe luna cu salariul primit.'}</h2><p>${linked?`Buget lunar: <strong>${money(budget())}</strong> · Alocat pe categorii: <strong>${money(allocated)}</strong> · <span class="${unallocated<0?'red':''}">${unallocated<0?'Alocat în plus':'De repartizat'}: <strong>${money(Math.abs(unallocated))}</strong></span>`:'Introdu salariul ca venit și buget lunar, apoi alege cât aloci fiecărei categorii.'}</p></div><div class="salary-actions"><button class="button primary" data-action="salary">${icon(linked?'pencil':'plus')}${linked?'Editează bugetul':'Adaugă buget'}</button><a class="button" href="#categories">${icon('shapes')}Împarte pe categorii</a></div></section>`;
}
function render(){const titles=pages[page];$('#breadcrumb').textContent=titles[0];$('#page-title').innerHTML=esc(titles[1])+'<span>.</span>';$('#page-subtitle').textContent=titles[2];$('#month-label').textContent=monthName();$('#month').value=month;document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);a.dataset.page===page?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');a.title=pages[a.dataset.page][0];});applyAppearance();$('#content').innerHTML=page==='dashboard'?`${metrics()}${salaryPlanning()}${charts()}<div class="insight">${icon('sparkles')}<span><strong>Mai multă claritate, mai puține griji.</strong> ${budget()?'Urmărește-ți bugetul și fă loc lucrurilor care contează.':'Stabilește bugetul lunii pentru a ști cât mai poți cheltui.'}</span><button class="text-button" data-action="budget">${budget()?'Editează bugetul':'Setează bugetul'} ${icon('arrow-right')}</button></div>${transactions()}`:page==='transactions'?transactions():page==='budgets'?budgetView():page==='categories'?categoriesView():page==='reports'?reportsView():settingsView();icons();}
function renderTable(){$('#table-area').innerHTML=transactionRows();icons();}
function openModal(type,id){modal={type,id};$('#form-error').textContent='';$('#save').className='button primary';$('#save').textContent='Salvează';const t=state.transactions.find(t=>t.id===id),c=state.categories.find(c=>c.id===id);const label=(name,html)=>`<label>${name}${html}</label>`;if(type==='transaction'){$('#dialog-title').textContent=t?'Editează tranzacția':'Adaugă tranzacție';$('#form-fields').innerHTML=`<div class="type-switch"><label><input type="radio" name="type" value="expense" ${!t||t.type==='expense'?'checked':''}><span>${icon('arrow-up-right')}Cheltuială</span></label><label><input type="radio" name="type" value="income" ${t?.type==='income'?'checked':''}><span>${icon('arrow-down-left')}Venit</span></label></div>${label('Denumire',`<input name="name" required maxlength="100" placeholder="Ex. Cumpărături săptămânale" value="${esc(t?.name||'')}">`)}<div class="field-pair">${label('Sumă (RON)',`<input name="amount" inputmode="decimal" required placeholder="0,00" value="${t?(t.amount/100).toFixed(2).replace('.',','):''}">`)}${label('Dată',`<input name="date" type="date" required value="${t?.date||(today().startsWith(month)?today():month+'-01')}">`)}</div>${label('Categorie',`<select name="category" required>${state.categories.filter(c=>!c.isGroup||t?.category===c.id).map(c=>`<option value="${c.id}" ${t?.category===c.id?'selected':''}>${esc(categoryLabel(c,state.categories))}${c.isGroup?' (categorie anterioară)':''}</option>`).join('')}</select>`)}${label('Descriere (opțional)',`<textarea name="description" maxlength="500" placeholder="Un detaliu de care vrei să-ți amintești...">${esc(t?.description||'')}</textarea>`)}`;}
else if(type==='salary'){
const linked=state.transactions.find(t=>t.salaryMonth===month),incomes=monthRows().filter(t=>t.type==='income'),suggested=linked||incomes.find(t=>/^salariu(?:\s|$)/i.test(t.name));
$('#dialog-title').textContent=linked?'Editează bugetul din salariu':'Adaugă buget din salariu';
$('#form-fields').innerHTML=`<p class="delete-copy">${esc(monthName())} · Introdu salariul primit. Suma se salvează ca <strong>venit</strong> și <strong>buget lunar</strong>. Apoi o împarți în Categorii. Alocările existente se păstrează.</p>${!linked&&incomes.length?label('Tranzacția de venit',`<select name="incomeId"><option value="">Adaugă un venit nou: Salariu</option>${incomes.map(t=>`<option value="${t.id}" ${suggested?.id===t.id?'selected':''}>${esc(t.name)} · ${money(t.amount)}</option>`).join('')}</select><span style="font-size:10px">Dacă ai introdus deja salariul în Tranzacții, selectează-l pentru a evita dublarea.</span>`):`<input type="hidden" name="incomeId" value="${linked?.id||''}">`}<div class="field-pair">${label('Salariu primit (RON)',`<input name="amount" inputmode="decimal" required placeholder="Introdu suma" value="${suggested?(suggested.amount/100).toFixed(2).replace('.',','):''}">`)}${label('Data încasării',`<input name="date" type="date" required min="${month}-01" max="${month}-${new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate()}" value="${suggested?.date||(today().startsWith(month)?today():month+'-01')}">`)}</div><span class="muted" style="font-size:10px">Editarea actualizează același venit. Bugetele din alte luni rămân neschimbate.</span>`;
}
else if(type==='budget'){$('#dialog-title').textContent='Bugetul lunii';$('#form-fields').innerHTML=`<p class="delete-copy">Alege cât vrei să aloci pentru ${esc(monthName())}. Poți reveni oricând asupra sumei.</p>${label('Buget lunar (RON)',`<input name="amount" inputmode="decimal" required value="${(budget()/100).toFixed(2).replace('.',',')}">`)}<span class="muted" style="font-size:10px">Valoarea 0 dezactivează bugetul pentru această lună.</span>`;}
else if(type==='category-budget'){$('#dialog-title').textContent='Buget · '+c.name;const amount=state.categoryBudgets?.[month]?.[id]||0;$('#form-fields').innerHTML=`<p class="delete-copy">${esc(monthName())} · Introdu suma pe care o aloci pentru <strong>${esc(c.name)}</strong>. ${c.id==='cat-4'?'Pentru datorii, aceasta este suma pe care intenționezi să o achiți în luna selectată. Înregistrează plățile ca tranzacții de cheltuială în această categorie.':''}</p>${label('Sumă alocată (RON)',`<input name="amount" inputmode="decimal" required placeholder="Introdu suma" value="${amount?(amount/100).toFixed(2).replace('.',','):''}">`)}<span class="muted" style="font-size:10px">0 elimină bugetul categoriei pentru această lună. Tranzacțiile rămân salvate. Bugetul general nu se modifică automat.</span>`;}
else if(type==='category'){$('#dialog-title').textContent=c?'Redenumește categoria':'O categorie nouă';$('#form-fields').innerHTML=label('Numele categoriei',`<input name="name" required maxlength="40" value="${esc(c?.name||'')}" placeholder="Ex. Animale de companie">`);}
else if(type==='delete-category'){$('#dialog-title').textContent='Ștergi categoria?';const count=state.transactions.filter(t=>t.category===id).length;$('#form-fields').innerHTML=`<p class="delete-copy">Categoria <strong>${esc(c.name)}</strong> și bugetele ei din toate lunile vor fi șterse. ${count?`${count} tranzacții vor fi mutate în categoria „Alte cheltuieli”.`:'Tranzacțiile tale nu vor fi afectate.'}</p>`;$('#save').textContent='Șterge categoria';$('#save').className='button danger';}
else if(type==='delete'){$('#dialog-title').textContent='Ștergi tranzacția?';$('#form-fields').innerHTML=`<p class="delete-copy"><strong>${esc(t.name)}</strong> · ${money(t.amount)}<br>Tranzacția va fi eliminată, iar totalurile vor fi recalculate. ${t.salaryMonth?'Fiind salariul asociat bugetului, se elimină și bugetul general al lunii. Alocările pe categorii se păstrează.':''} Această acțiune nu poate fi anulată.</p>`;$('#save').textContent='Șterge tranzacția';$('#save').className='button danger';}
icons();$('#dialog').showModal();requestAnimationFrame(()=>$('#form-fields input[name="name"],#form-fields input[name="amount"],#save')?.focus());}
$('#form').addEventListener('change',e=>{if(modal?.type==='salary'&&e.target.name==='incomeId'){const t=state.transactions.find(t=>t.id===e.target.value);$('#form [name="amount"]').value=t?(t.amount/100).toFixed(2).replace('.',','):'';$('#form [name="date"]').value=t?.date||(today().startsWith(month)?today():month+'-01');}});
$('#form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);try{let msg='Modificări salvate.';if(modal.type==='transaction'){const amount=parseMoney(f.get('amount')),name=f.get('name').trim(),date=f.get('date');if(!name)throw Error('Denumirea nu poate fi goală.');if(amount<=0)throw Error('Suma trebuie să fie mai mare decât zero.');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date.slice(0,4)==='0000'||new Date(date+'T12:00:00').toISOString().slice(0,10)!==date)throw Error('Alege o dată validă.');const entry={id:modal.id||crypto.randomUUID(),name,amount,date,type:f.get('type'),category:f.get('category'),description:f.get('description').trim()};mutate(s=>{const previous=s.transactions.find(t=>t.id===entry.id);if(previous?.salaryMonth){if(entry.type!=='income')throw Error('Salariul asociat bugetului trebuie să rămână un venit.');if(!entry.date.startsWith(previous.salaryMonth+'-'))throw Error('Salariul asociat bugetului trebuie să rămână în aceeași lună.');entry.salaryMonth=previous.salaryMonth;s.budgets[entry.salaryMonth]=entry.amount;}const i=s.transactions.findIndex(t=>t.id===entry.id);if(i<0)s.transactions.push(entry);else s.transactions[i]=entry;});month=date.slice(0,7);filter={search:'',category:'',type:''};tablePage=1;msg=modal.id?'Tranzacția a fost actualizată.':'Tranzacția a fost adăugată.';}
else if(modal.type==='salary'){const amount=parseMoney(f.get('amount'));mutate(s=>setMonthlySalary(s,{month,amount,date:f.get('date'),transactionId:f.get('incomeId')||null}));msg='Salariul și bugetul lunar au fost salvate. Îl poți împărți în Categorii.';}
else if(modal.type==='budget'){const amount=parseMoney(f.get('amount'));mutate(s=>s.budgets[month]=amount);msg='Bugetul lunii a fost actualizat.';}
else if(modal.type==='category-budget'){const amount=parseMoney(f.get('amount'));mutate(s=>{s.categoryBudgets ??= {};s.categoryBudgets[month] ??= {};if(amount)s.categoryBudgets[month][modal.id]=amount;else delete s.categoryBudgets[month][modal.id];});msg='Bugetul categoriei a fost actualizat.';}
else if(modal.type==='category'){const name=f.get('name').trim();if(!name)throw Error('Introdu numele categoriei.');if(state.categories.some(c=>c.id!==modal.id&&c.name.toLocaleLowerCase('ro-RO')===name.toLocaleLowerCase('ro-RO')))throw Error('Există deja o categorie cu acest nume.');mutate(s=>{if(modal.id)s.categories.find(c=>c.id===modal.id).name=name;else s.categories.push({id:crypto.randomUUID(),name,custom:true,color:['#818cf8','#38bdf8','#fbbf24','#f472b6'][s.categories.length%4],icon:'tag'});});msg='Categoria a fost salvată.';}
else if(modal.type==='delete'){mutate(s=>{const t=s.transactions.find(t=>t.id===modal.id);if(t?.salaryMonth)delete s.budgets[t.salaryMonth];s.transactions=s.transactions.filter(t=>t.id!==modal.id);});msg='Tranzacția a fost ștearsă.';}
else if(modal.type==='delete-category'){mutate(s=>{const cat=s.categories.find(c=>c.id===modal.id);if(!cat?.custom)throw Error('Categoria implicită nu poate fi ștearsă.');s.transactions.forEach(t=>{if(t.category===modal.id)t.category='cat-8';});s.categories=s.categories.filter(c=>c.id!==modal.id);Object.values(s.categoryBudgets||{}).forEach(b=>delete b[modal.id]);});if(filter.category===modal.id)filter.category='';msg='Categoria a fost ștearsă.';}
$('#dialog').close();render();toast(msg);}catch(err){$('#form-error').textContent=err.message;}});
function download(rows){if(!rows.length){toast('Nu există tranzacții de exportat.');return;}const url=URL.createObjectURL(new Blob([csv(rows,state.categories)],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`JARVIS-${month}-${rows.length}-tranzactii.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exportul CSV este pregătit.');}
function toggleTheme(){mutate(s=>s.theme=s.theme==='dark'?'light':'dark');render();}
function action(name){try{if(name==='add')openModal('transaction');if(name==='budget')openModal('budget');if(name==='salary')openModal('salary');if(name==='add-category')openModal('category');if(name==='export')download(filtered());if(name==='export-all')download(state.transactions);if(name==='report-export')download(monthRows());if(name==='theme')toggleTheme();if(name==='reset-filters'){filter={search:'',category:'',type:''};tablePage=1;render();}if(name==='table-prev'){tablePage--;renderTable();}if(name==='table-next'){tablePage++;renderTable();}if(name==='demo'){if(state.transactions.length)return;mutate(s=>{s.transactions=demoTransactions(month);s.budgets[month]=600000;});render();toast('Date demonstrative adăugate în luna selectată.');}}catch(e){toast(e.message);}}
$('#content').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action)action(b.dataset.action);if(b.dataset.edit)openModal('transaction',b.dataset.edit);if(b.dataset.delete)openModal('delete',b.dataset.delete);if(b.dataset.categoryBudget)openModal('category-budget',b.dataset.categoryBudget);if(b.dataset.editCategory)openModal('category',b.dataset.editCategory);if(b.dataset.deleteCategory)openModal('delete-category',b.dataset.deleteCategory);});
$('#content').addEventListener('input',e=>{if(e.target.id==='search'){filter.search=e.target.value;tablePage=1;renderTable();}});
$('#content').addEventListener('change',e=>{if(e.target.id==='category-filter')filter.category=e.target.value;else if(e.target.id==='type-filter')filter.type=e.target.value;else return;tablePage=1;renderTable();});
$('#add').onclick=()=>openModal('transaction');$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#theme').onclick=()=>action('theme');$('#collapse').onclick=()=>{try{mutate(s=>s.collapsed=!s.collapsed);applyAppearance();icons();}catch(e){toast(e.message);}};
function changeMonth(value){if(!/^\d{4}-\d{2}$/.test(value)||value<'1900-01'||value>'9999-12')return;month=value;tablePage=1;render();}
$('#month').min='1900-01';$('#month').max='9999-12';$('#month').onchange=e=>changeMonth(e.target.value);function shiftMonth(delta){const d=new Date(month+'-01T12:00:00');d.setMonth(d.getMonth()+delta);changeMonth(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'));}$('#prev-month').onclick=()=>shiftMonth(-1);$('#next-month').onclick=()=>shiftMonth(1);
function route(){const key=location.hash.slice(1);page=pages[key]?key:'dashboard';tablePage=1;filter={search:'',category:'',type:''};render();}window.addEventListener('hashchange',route);window.addEventListener('storage',e=>{if(e.key==='jarvis-expencer-v1'){try{state=loadState();storageFailed=false;render();toast('Datele au fost actualizate din altă filă.');}catch{storageFailed=true;toast('Datele din stocare nu pot fi citite.');}}});
route();if(storageFailed)toast('Stocarea nu poate fi citită. Datele existente nu vor fi suprascrise.');
